package com.smarthub.plus;
import android.os.Bundle;
import android.widget.*;
import java.net.*;
import java.util.concurrent.*;
import org.json.*;
/** Explicit correction for satellite names that differ from the public logo catalogue. */
public final class ChannelIdentityActivity extends HubActivity {
 private final ExecutorService io=Executors.newSingleThreadExecutor();private LinearLayout results;private TextView status;private EditText query;private SatelliteState state;private int generation;private boolean closed;
 @Override public void onCreate(Bundle bundle){super.onCreate(bundle);state=SatelliteState.read(this);LinearLayout body=page(tx("هوية القناة وشعارها","Channel identity and logo"));note(body,tx("القناة المرصودة: ","Observed channel: ")+state.channelName);note(body,tx("تُجلب الشعارات تلقائياً باستخدام أسماء القنوات الإنجليزية، مع تفضيل الشعار الإنجليزي وجودة الصورة. لا يحتاج العرض إلى اختيار يدوي؛ هذه الصفحة لتصحيح اختياري فقط.","Logos load automatically from English channel names, preferring English artwork and higher resolution. Manual selection is optional correction only."));String attribution=prefs().getString("online_logo_attribution:"+state.channelId,"");if(!attribution.isEmpty()){note(body,attribution);String page=prefs().getString("online_logo_page:"+state.channelId,"");if(page.startsWith("https://commons.wikimedia.org/")||page.equals("https://github.com/tv-logo/tv-logos"))action(body,tx("مصدر الشعار وترخيصه","Logo source and license"),()->{try{startActivity(new android.content.Intent(android.content.Intent.ACTION_VIEW,android.net.Uri.parse(page)));}catch(Exception ignored){}});}query=field(body,tx("اسم القناة بالعربية أو الإنجليزية","Channel name in Arabic or English"),state.channelName);status=text("",15,false);body.addView(status);action(body,tx("البحث عبر الإنترنت","Search online"),this::search);action(body,tx("إزالة الربط اليدوي","Remove manual mapping"),()->{prefs().edit().remove("satellite_logo_id:"+state.channelId).apply();status.setText(tx("تمت العودة للمطابقة التلقائية","Automatic matching restored"));});results=col();body.addView(results);}
 private void search(){if(state.channelId.isEmpty()){status.setText(tx("افتح قناة أولاً حتى تُرصد هويتها","Open a channel first so its identity can be observed"));return;}String name=query.getText().toString().trim();if(name.length()<2)return;final int token=++generation;results.removeAllViews();status.setText(tx("جارٍ البحث…","Searching…"));io.execute(()->{try{JSONArray channels=new ChannelCatalogue(this).search(name);runOnUiThread(()->{if(closed||token!=generation)return;status.setText(channels.length()==0?tx("لا توجد مطابقة؛ جرّب الاسم الأصلي","No match; try its original name"):tx("اختر القناة الصحيحة","Choose the correct channel"));for(int n=0;n<channels.length();n++){JSONObject item=channels.optJSONObject(n);if(item==null)continue;String id=item.optString("id"),label=item.optString("name")+" · "+item.optString("country")+"\n"+id;action(results,label,()->{prefs().edit().putString("satellite_logo_id:"+state.channelId,id).apply();status.setText(tx("حُفظ الربط؛ سيُحدّث الشعار عند العودة للبث","Mapping saved; the logo will refresh when you return to TV"));});}});}catch(Exception e){runOnUiThread(()->{if(!closed&&token==generation)status.setText(tx("فشل الاتصال بمصدر الشعارات","Cannot reach the online logo catalogue"));});}});}
 @Override protected void onDestroy(){closed=true;generation++;io.shutdownNow();super.onDestroy();}
}
